import { Component, OnInit } from '@angular/core';
import { FormGroup,FormControl, Validators, FormBuilder } from '@angular/forms';
import { ModalController, NavParams } from '@ionic/angular';
import { CalendarComponentOptions } from 'ion2-calendar';
import { CalendarMode, Step } from 'ionic2-calendar/calendar';
import moment, { Moment } from "moment";
import { AlertService } from 'src/app/services/alert.service';
import { UploadService } from 'src/app/services/emis/upload.service';
import { IonicStorageService } from 'src/app/services/ionic-storage/ionic-storage.service';
import { NetworkService } from 'src/app/services/network-service';

@Component({
  selector: 'app-cwsn-calendar',
  templateUrl: './cwsn-calendar.page.html',
  styleUrls: ['./cwsn-calendar.page.scss'],
})
export class CwsnCalendarPage implements OnInit {

  form:FormGroup;
  calendarOptions: CalendarComponentOptions = {
    from: new Date(2015, 0, 1),  // January 1, 2020
  };
  showCalender: boolean
  showWeekly: boolean
  showTab: boolean
  showHomeworkDaily: boolean
  showHomeworkWeely: boolean

  Dailydate: Date;
  WeeklydateRange: { from: string; to: string; };
  type: 'string'
  optionsRange: CalendarComponentOptions = {
  pickMode: 'multi',
  from: new Date(2015, 0, 1),
  };
  optionsMulti: CalendarComponentOptions = {
    pickMode: 'multi'
  };
  minDate: string;
  // selectedDate: any[];
  events: any[];
  IndivdUser: any[];
  dateChk: any;
  selectedDate: string;
  allData: any[];
  hideCalendar: boolean;
  showData: any;
  imageData: any;
  imageData1: any;
  currNetWrkSts: any;

  constructor(private modalCtrl: ModalController, private navparms: NavParams,private uploadService: UploadService,
    private alertService: AlertService,private ionicstorage: IonicStorageService,private networkService: NetworkService) {
    
   }

    ngOnInit() {
      this.currNetWrkSts = this.networkService.getCurrentNetworkStatus();
      this.hideCalendar = false;
    }

     onChange($event) {
      this.hideCalendar = false;
      this.showData = null;
      if(this.allData == undefined){
        this.alertService.error('Invalid Date Select')
        this.modalCtrl.dismiss('success');
      }
      else{
        if(this.allData.length == 1){
          if(this.allData.length < $event.length){
            this.modalCtrl.dismiss('success');
            this.alertService.error('Invalid Date Select')
  
          }
          else{
            this.showData = this.allData[0]
            this.imageCall();
            this.hideCalendar = true;
          }
        }
        else{
          if(this.allData.length < $event.length){
            this.modalCtrl.dismiss('success');
            this.alertService.error('Invalid Date Select')
  
          }
          else{
            for(let i=0;i<this.allData.length;i++){
              for(let j=0;j<$event.length;j++){
                if(this.allData[i].screening_date != $event[j]){
                  this.showData = this.allData[i]
                }
              }
            }
            if(this.showData){
              this.hideCalendar = true;
              this.imageCall();
            }
          }
          
        }
      }
      
    }

    imageCall(){
      if (this.currNetWrkSts == 0) { 
        var bucketName = "renewalapplicationemis";
        var filename = this.showData.before_screening_photo;
        let expiry: number = 1800;
     
        this.uploadService.getUploadedFiles(bucketName, filename, expiry).subscribe(async (result) => {
          if (result) {
            this.imageData = result.url;
            this.imageCallAfter();
          }
          else {
            this.alertService.error('Error in getting image file');
          }
        });
      }
       else{
          this.alertService.error('Please Check Your Internet Connectivity');
       } 
    }

    imageCallAfter(){
        var bucketName = "renewalapplicationemis";
        var filename = this.showData.after_screening_photo;
        let expiry: number = 1800;
     
        this.uploadService.getUploadedFiles(bucketName, filename, expiry).subscribe(async (result) => {
          if (result) {
            this.imageData1 = result.url;
          }
          else {
            this.alertService.error('Error in getting image file');
          }
        });
      
    }


  onSave(){
     this.modalCtrl.dismiss('success');
  }

  goBack(){
    if(this.hideCalendar == false){
      this.modalCtrl.dismiss();
    }
    else{
      this.backCall();
    }
    
  }

  backCall(){
      if(this.IndivdUser){
        this.dateChk = [];
        this.allData = [];
        for(let z=0;z<this.IndivdUser.length;z++){
          if(this.IndivdUser[z].screening_date != '0000-00-00'){
            var data = new Date(this.IndivdUser[z].screening_date).toISOString();
              this.dateChk.push(data)
              this.allData.push(this.IndivdUser[z])
          }
        }
        if(this.allData){
          this.hideCalendar = false
        }
      }
     var channelArray1: Array<string> = [this.dateChk];
     this.selectedDate = channelArray1[0];
  }

  ionViewWillEnter(){
    let newDate = this.navparms.get('selectDate');
    let userVal = this.navparms.get('userId');
    this.IndivdUser = [];
      for(let i=0;i<newDate.length;i++){
        for(let j=0;j<newDate[i].length;j++){
          if(newDate[i][j].user_id == userVal){
            this.IndivdUser.push(newDate[i][j])
          }
        }
      }

      if(this.IndivdUser){
        this.dateChk = [];
        this.allData = [];
        for(let z=0;z<this.IndivdUser.length;z++){
          if(this.IndivdUser[z].screening_date != '0000-00-00'){
            var data = new Date(this.IndivdUser[z].screening_date).toISOString();
            // if(this.dateChk == ''){
              this.dateChk.push(data)
              this.allData.push(this.IndivdUser[z])
            // }
            // else{
            //   this.dateChk = this.dateChk + ' ' + data
            // }
          }
        }
      }
      // console.log(this.dateChk,"this.dateChk")
    //   var data = new Date(newDate[0][0].screening_date).toISOString();
    //  var data1 = new Date(newDate[0][1].screening_date).toISOString();
    //  var channelArray: Array<string> = [data, data1];
     var channelArray1: Array<string> = [this.dateChk];
     this.selectedDate = channelArray1[0];
     
  }

}
